// Global sink to prevent compiler optimizations from dead-code eliminating results
var (
	benchSinkBuf  []byte
	benchSinkHead *[]byte
	benchSinkN    int
)

// ============================================================================
// 1. UNIT & BASIC INTEGRITY TESTS
// ============================================================================

func TestEmptyPop(t *testing.T) {
	rb := NewBufferRing(16)

	if rb.Length() != 0 {
		t.Fatalf("expected length 0, got %d", rb.Length())
	}

	buf, head, ok := rb.Pop()
	if ok || buf != nil || head != nil {
		t.Fatalf("expected pop from empty ring to return (nil, nil, false), got (%v, %v, %v)", buf, head, ok)
	}

	dst := make([]byte, 10)
	n, rec := rb.PartialRead(dst)
	if n != 0 || rec != nil {
		t.Fatalf("expected consumeFront on empty ring to return (0, nil), got (%d, %v)", n, rec)
	}
}

func TestFIFOOrderAndDataIntegrity(t *testing.T) {
	rb := NewBufferRing(16)
	count := 1000

	type sample struct {
		buf  []byte
		head *[]byte
	}
	samples := make([]sample, count)

	for i := 0; i < count; i++ {
		payload := []byte(fmt.Sprintf("item-%06d", i))
		samples[i] = sample{buf: payload, head: &payload}
		rb.Push(payload, &payload)
	}

	if rb.Length() != count {
		t.Fatalf("expected length %d, got %d", count, rb.Length())
	}

	for i := 0; i < count; i++ {
		buf, head, ok := rb.Pop()
		if !ok {
			t.Fatalf("expected pop ok=true at index %d", i)
		}
		if !bytes.Equal(buf, samples[i].buf) {
			t.Fatalf("payload mismatch at %d: expected %s, got %s", i, string(samples[i].buf), string(buf))
		}
		if head != samples[i].head {
			t.Fatalf("head pointer mismatch at index %d", i)
		}
	}

	if rb.Length() != 0 {
		t.Fatalf("expected ring buffer to be empty, got length %d", rb.Length())
	}
}

func TestGrowPreservesDataAcrossWrapAround(t *testing.T) {
	rb := NewBufferRing(4)

	// Churn through buffer to advance chunks
	for i := 0; i < 20; i++ {
		data := []byte(fmt.Sprintf("churn-%d", i))
		rb.Push(data, &data)
		_, _, _ = rb.Pop()
	}

	// Push 32 items to force dynamic grow across multiple chunks
	itemsToPush := 32
	for i := 0; i < itemsToPush; i++ {
		data := []byte(fmt.Sprintf("data-%02d", i))
		rb.Push(data, &data)
	}

	if rb.Length() != itemsToPush {
		t.Fatalf("expected length %d after grow, got %d", itemsToPush, rb.Length())
	}

	for i := 0; i < itemsToPush; i++ {
		expected := fmt.Sprintf("data-%02d", i)
		buf, _, ok := rb.Pop()
		if !ok {
			t.Fatalf("expected item %d to pop successfully", i)
		}
		if string(buf) != expected {
			t.Fatalf("item corrupted during grow: expected %s, got %s", expected, string(buf))
		}
	}
}

func TestConsumeFrontPartialStream(t *testing.T) {
	rb := NewBufferRing(2)

	p1 := []byte("ABCDEFGH")
	p2 := []byte("12345678")
	h1 := &p1
	h2 := &p2

	rb.Push(p1, h1)
	rb.Push(p2, h2)

	dst := make([]byte, 3)

	// Read "ABC"
	n, rec := rb.PartialRead(dst)
	if n != 3 || string(dst[:n]) != "ABC" || rec != nil {
		t.Fatalf("Read 1 failed: %d, %s, %v", n, string(dst[:n]), rec)
	}

	// Read "DEF"
	n, rec = rb.PartialRead(dst)
	if n != 3 || string(dst[:n]) != "DEF" || rec != nil {
		t.Fatalf("Read 2 failed: %d, %s, %v", n, string(dst[:n]), rec)
	}

	// Read "GH" -> Recycle h1
	n, rec = rb.PartialRead(dst)
	if n != 2 || string(dst[:n]) != "GH" || rec != h1 {
		t.Fatalf("Read 3 failed: %d, %s, %v", n, string(dst[:n]), rec)
	}

	// Read entire "12345678" -> Recycle h2
	dst8 := make([]byte, 8)
	n, rec = rb.PartialRead(dst8)
	if n != 8 || string(dst8[:n]) != "12345678" || rec != h2 {
		t.Fatalf("Read 4 failed: %d, %s, %v", n, string(dst8[:n]), rec)
	}

	if rb.Length() != 0 {
		t.Fatalf("expected length 0, got %d", rb.Length())
	}
}

func TestNilAndEmptyByteSlices(t *testing.T) {
	rb := NewBufferRing(4)

	emptySlice := []byte{}
	var nilSlice []byte
	h1 := &emptySlice
	h2 := &nilSlice

	rb.Push(emptySlice, h1)
	rb.Push(nilSlice, h2)

	buf, h, ok := rb.Pop()
	if !ok || buf == nil || len(buf) != 0 || h != h1 {
		t.Fatalf("expected empty slice pop, got (%v, %v, %v)", buf, h, ok)
	}

	buf, h, ok = rb.Pop()
	if !ok || buf != nil || h != h2 {
		t.Fatalf("expected nil slice pop, got (%v, %v, %v)", buf, h, ok)
	}
}

// ============================================================================
// 2. INTENSE CONCURRENCY & DATA INTEGRITY STRESS TESTS
// ============================================================================

// TestSPSC_MassiveMultiMillionStream streams 5,000,000 sequential uint64 payloads
// and computes continuous running bitwise checksums on both ends.
func TestSPSC_MassiveMultiMillionStream(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping heavy stress test in short mode")
	}

	rb := NewBufferRing(8) // Start tiny to force massive progressive chunk expansions
	const totalItems = 5_000_000

	var producerXOR uint64
	var consumerXOR uint64

	var wg sync.WaitGroup
	wg.Add(2)

	// Producer
	go func() {
		defer wg.Done()
		scratch := make([]byte, 8)
		for i := uint64(1); i <= totalItems; i++ {
			b := make([]byte, 8)
			binary.LittleEndian.PutUint64(b, i)
			producerXOR ^= i
			rb.Push(b, &scratch)
		}
	}()

	// Consumer
	go func() {
		defer wg.Done()
		received := 0
		for received < totalItems {
			buf, _, ok := rb.Pop()
			if ok {
				val := binary.LittleEndian.Uint64(buf)
				consumerXOR ^= val
				received++
			} else {
				runtime.Gosched()
			}
		}
	}()

	wg.Wait()

	if producerXOR != consumerXOR {
		t.Fatalf("checksum mismatch: producerXOR=%x, consumerXOR=%x", producerXOR, consumerXOR)
	}
	if rb.Length() != 0 {
		t.Fatalf("expected drained buffer, got length %d", rb.Length())
	}
}

// TestSPSC_AsymmetricRates tests burst buffering (fast producer) and starvation (fast consumer).
func TestSPSC_AsymmetricRates(t *testing.T) {
	rb := NewBufferRing(4)
	const numBursts = 50
	const burstSize = 1000

	var wg sync.WaitGroup
	wg.Add(2)
	consumerErr := make(chan error, 1)

	// Producer: sends in heavy fast bursts, then sleeps
	go func() {
		defer wg.Done()
		val := 0
		for b := 0; b < numBursts; b++ {
			for i := 0; i < burstSize; i++ {
				payload := []byte(fmt.Sprintf("burst-%d", val))
				rb.Push(payload, &payload)
				val++
			}
			time.Sleep(time.Millisecond * 2) // let consumer work through backlog
		}
	}()

	// Consumer: continuously drains
	go func() {
		defer wg.Done()
		expected := 0
		totalExpected := numBursts * burstSize
		for expected < totalExpected {
			buf, _, ok := rb.Pop()
			if ok {
				expStr := fmt.Sprintf("burst-%d", expected)
				if string(buf) != expStr {
					consumerErr <- fmt.Errorf("expected %s, got %s", expStr, string(buf))
					return
				}
				expected++
			} else {
				runtime.Gosched()
			}
		}
	}()

	wg.Wait()
	select {
	case err := <-consumerErr:
		t.Fatal(err)
	default:
	}
}

// TestSPSC_FuzzyFragmentedStream pushes random variable-size byte slices (1 to 8192 bytes)
// and consumes them with random variable-size read buffers (1 to 4096 bytes).
// Checks complete SHA-256 byte stream integrity and head pointer recycling.
func TestSPSC_FuzzyFragmentedStream(t *testing.T) {
	rb := NewBufferRing(4)
	const totalChunks = 5000

	// Generate deterministic test payloads
	rnd := rand.New(rand.NewSource(42))
	chunks := make([][]byte, totalChunks)
	var fullProducerStream bytes.Buffer

	for i := 0; i < totalChunks; i++ {
		sz := rnd.Intn(4096) + 1
		chunk := make([]byte, sz)
		rnd.Read(chunk)
		chunks[i] = chunk
		fullProducerStream.Write(chunk)
	}

	expectedHash := sha256.Sum256(fullProducerStream.Bytes())
	totalBytesToReceive := fullProducerStream.Len()

	var wg sync.WaitGroup
	wg.Add(2)

	// Producer
	go func() {
		defer wg.Done()
		for i := 0; i < totalChunks; i++ {
			c := chunks[i]
			rb.Push(c, &c)
		}
	}()

	// Consumer
	var receivedStream bytes.Buffer
	recycledCount := 0

	go func() {
		defer wg.Done()
		cRnd := rand.New(rand.NewSource(99))
		readBuf := make([]byte, 8192)

		for receivedStream.Len() < totalBytesToReceive {
			readSize := cRnd.Intn(4096) + 1
			n, rec := rb.PartialRead(readBuf[:readSize])
			if n > 0 {
				receivedStream.Write(readBuf[:n])
			}
			if rec != nil {
				recycledCount++
			}
			if n == 0 {
				runtime.Gosched()
			}
		}
	}()

	wg.Wait()

	actualHash := sha256.Sum256(receivedStream.Bytes())
	if expectedHash != actualHash {
		t.Fatalf("stream SHA256 mismatch!\nExpected: %x\nActual:   %x", expectedHash, actualHash)
	}
	if recycledCount != totalChunks {
		t.Fatalf("expected %d recycled head pointers, got %d", totalChunks, recycledCount)
	}
}

// TestSPSC_BurstyWavePatterns alternates between pushing bursts and popping partial batches.
func TestSPSC_BurstyWavePatterns(t *testing.T) {
	rb := NewBufferRing(8)
	counter := 0
	readCounter := 0

	for cycle := 0; cycle < 500; cycle++ {
		toPush := (cycle % 20) + 5
		toPop := (cycle % 15) + 2

		for i := 0; i < toPush; i++ {
			p := []byte(fmt.Sprintf("wave-%d", counter))
			rb.Push(p, &p)
			counter++
		}

		for i := 0; i < toPop; i++ {
			if rb.Length() == 0 {
				break
			}
			buf, _, ok := rb.Pop()
			if ok {
				exp := fmt.Sprintf("wave-%d", readCounter)
				if string(buf) != exp {
					t.Fatalf("wave integrity failed: expected %s, got %s", exp, string(buf))
				}
				readCounter++
			}
		}
	}

	// Drain remainder
	for rb.Length() > 0 {
		buf, _, ok := rb.Pop()
		if ok {
			exp := fmt.Sprintf("wave-%d", readCounter)
			if string(buf) != exp {
				t.Fatalf("wave drain failed: expected %s, got %s", exp, string(buf))
			}
			readCounter++
		}
	}
}

