// BenchmarkSPSC_UltraThroughput measures raw concurrent message passing throughput (Million ops/sec).
func BenchmarkSPSC_UltraThroughput(b *testing.B) {
	rb := NewBufferRing(8)
	data := []byte("msgcccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc")
	head := &data

	b.ReportAllocs()
	b.ResetTimer()

	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			rb.Push(data, head)
		}
	}()

	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			for {
				buf, h, ok := rb.Pop()
				if ok {
					benchSinkBuf = buf
					benchSinkHead = h
					break
				}
				// Low latency tight spin
			}
		}
	}()

	wg.Wait()
}

// BenchmarkChannel_Comparison compares SPSC performance with native buffered Go channels.
func BenchmarkChannel_Comparison(b *testing.B) {
	type item struct {
		buf  []byte
		head *[]byte
	}
	ch := make(chan item, 8192)
	data := []byte("")
	head := &data
	it := item{buf: data, head: head}

	b.ReportAllocs()
	b.ResetTimer()

	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			ch <- it
		}
	}()

	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			res := <-ch
			benchSinkBuf = res.buf
			benchSinkHead = res.head
		}
	}()

	wg.Wait()
}

// BenchmarkSPSC_ByteThroughput measures raw streaming bandwidth in GB/s across payload sizes.
func BenchmarkSPSC_ByteThroughput(b *testing.B) {
	payloadSizes := []int{64, 512, 1024, 1500, 2056, 4096, 8192, 16384, 32768, 65536, 131072}

	for _, sz := range payloadSizes {
		b.Run(fmt.Sprintf("%dB", sz), func(b *testing.B) {
			rb := NewBufferRing(8)
			data := make([]byte, sz)
			head := &data
			dst := make([]byte, sz)

			// Bound the maximum in-flight queue depth to prevent runaway memory
			const maxBacklog = 16384

			b.SetBytes(int64(sz))
			b.ReportAllocs()
			b.ResetTimer()

			var wg sync.WaitGroup
			wg.Add(2)

			// Producer with flow-control backpressure
			go func() {
				defer wg.Done()
				for i := 0; i < b.N; i++ {
					for rb.Length() >= maxBacklog {
						runtime.Gosched() // Wait for consumer when buffer reaches max backlog
					}
					rb.Push(data, head)
				}
			}()

			// Consumer
			go func() {
				defer wg.Done()
				for i := 0; i < b.N; i++ {
					for {
						n, rec := rb.PartialRead(dst)
						if n > 0 {
							benchSinkN = n
							benchSinkHead = rec
							break
						}
						runtime.Gosched() // Prevent CPU core starvation while waiting
					}
				}
			}()

			wg.Wait()
		})
	}

}

// BenchmarkSPSC_BatchPipelining tests throughput when producer and consumer operate in chunks.
func BenchmarkSPSC_BatchPipelining(b *testing.B) {
	batchSizes := []int{16, 64, 256, 1024, 2056}
	data := []byte("bench-payload")
	head := &data

	for _, batch := range batchSizes {
		b.Run(fmt.Sprintf("Batch-%d", batch), func(b *testing.B) {
			rb := NewBufferRing(batch * 4)
			b.ReportAllocs()
			b.ResetTimer()

			for i := 0; i < b.N; i++ {
				for j := 0; j < batch; j++ {
					rb.Push(data, head)
				}
				for j := 0; j < batch; j++ {
					buf, h, _ := rb.Pop()
					benchSinkBuf = buf
					benchSinkHead = h
				}
			}
		})
	}
}

