// BenchmarkSPSC_BoundedThroughput benchmarks true steady-state cross-core SPSC with backpressure.
func BenchmarkSPSC_BoundedThroughput(b *testing.B) {
	rb := NewBufferRing(8)
	data := []byte("")
	head := &data

	var wg sync.WaitGroup
	wg.Add(2)

	// Producer
	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			for rb.Length() >= 8192 {
				runtime.Gosched() // Backpressure: wait for consumer when full
			}
			rb.Push(data, head)
		}
	}()

	// Consumer
	go func() {
		defer wg.Done()
		for i := 0; i < b.N; i++ {
			for {
				buf, h, ok := rb.Pop()
				if ok {
					benchSinkBuf = buf
					benchSinkHead = h
					break
				}
				runtime.Gosched() // Yield CPU when empty to prevent cache-line thrashing
			}
		}
	}()

	b.ReportAllocs()
	b.ResetTimer()

	wg.Wait()
}

// Helper to get currently in-use heap bytes safely
func readHeapAlloc() uint64 {
	runtime.GC()
	runtime.GC() // Run twice to ensure finalizers and free-lists are flushed
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	return m.HeapAlloc
}

// TestMemoryNoLeakOnConsumeFront ensures that partial reads and buffer clearing don't leak memory.
func TestMemoryNoLeakOnConsumeFront(t *testing.T) {
	rb := NewBufferRing(512)
	const items = 50_000
	const chunkSize = 1024 // 1 KB each -> 50 MB total

	before := readHeapAlloc()

	for i := 0; i < items; i++ {
		b := make([]byte, chunkSize)
		rb.Push(b, &b)
	}

	dst := make([]byte, 256) // Read in 256B increments
	for rb.Length() > 0 {
		_, _ = rb.PartialRead(dst)
	}

	after := readHeapAlloc()

	var diffMB float64
	if after > before {
		diffMB = float64(after-before) / (1024 * 1024)
	} else {
		diffMB = 0 // Heap shrank back to baseline or lower
	}

	t.Logf("Heap before: %.2f MB, after draining 50MB via ConsumeFront: %.2f MB (Retained diff: %.2f MB)",
		float64(before)/(1024*1024), float64(after)/(1024*1024), diffMB)

	if diffMB > 10.0 {
		t.Fatalf("excessive memory retained: %.2f MB", diffMB)
	}
}

// TestMemoryFootprint_Lifecycle measures heap memory before, during peak load, and after drain.
func TestMemoryFootprint_Lifecycle(t *testing.T) {
	const numItems = 100_000
	const payloadSize = 16 << 10

	beforeAlloc := readHeapAlloc()

	rb := NewBufferRing(8)

	// Create payloads
	for i := 0; i < numItems; i++ {
		payload := make([]byte, payloadSize)
		rb.Push(payload, &payload)
	}

	peakAlloc := readHeapAlloc()
	retainedPerItem := float64(int64(peakAlloc)-int64(beforeAlloc)) / float64(numItems)

	t.Logf("=== Lifecycle Heap Metrics ===")
	t.Logf("Heap before push:                 %.2f MB", float64(beforeAlloc)/(1024*1024))
	t.Logf("Heap at peak (100k items): %.2f MB", float64(peakAlloc)/(1024*1024))
	t.Logf("Average footprint per item:       %.2f bytes (data + queue overhead)", retainedPerItem)

	// Drain everything
	for {
		_, _, ok := rb.Pop()
		if !ok {
			break
		}
	}

	postDrainAlloc := readHeapAlloc()
	t.Logf("Heap after drain + GC:            %.2f MB", float64(postDrainAlloc)/(1024*1024))

	// Verify that data payloads were properly freed from the heap
	if postDrainAlloc >= peakAlloc {
		t.Fatalf("memory leak detected: heap did not shrink after draining (peak: %d, post: %d)", peakAlloc, postDrainAlloc)
	}
}

// TestConsumeFront_NilBufferDoesNotLivelock tests that pushing nil buffers
// does not freeze the queue and properly recycles head tickets.
func TestConsumeFront_NilBufferDoesNotLivelock(t *testing.T) {
	rb := NewBufferRing(4)

	dummy1 := []byte("ticket-1")
	dummy2 := []byte("ticket-2")
	payload := []byte("hello world")
	dummy3 := &payload

	// 1. Push nil slice with head1
	rb.Push(nil, &dummy1)

	// 2. Push empty non-nil slice with head2
	rb.Push([]byte{}, &dummy2)

	// 3. Push real payload with head3
	rb.Push(payload, dummy3)

	dst := make([]byte, 32)

	// Read 1: Should retire nil buffer and return dummy1 ticket without blocking
	n, rec := rb.PartialRead(dst)
	if n != 0 || rec != &dummy1 {
		t.Fatalf("Read 1 failed: expected (0, &dummy1), got (%d, %v)", n, rec)
	}

	// Read 2: Should retire empty slice and return dummy2 ticket without blocking
	n, rec = rb.PartialRead(dst)
	if n != 0 || rec != &dummy2 {
		t.Fatalf("Read 2 failed: expected (0, &dummy2), got (%d, %v)", n, rec)
	}

	// Read 3: Should read real payload and return dummy3 ticket
	n, rec = rb.PartialRead(dst)
	if n != len(payload) || string(dst[:n]) != "hello world" || rec != dummy3 {
		t.Fatalf("Read 3 failed: expected (%d, 'hello world', dummy3), got (%d, '%s', %v)",
			len(payload), n, string(dst[:n]), rec)
	}

	// Queue should now be completely drained
	if rb.Length() != 0 {
		t.Fatalf("expected length 0, got %d", rb.Length())
	}
}

// TestConsumeFront_ConsecutiveNilBuffers tests a burst of nil slices.
func TestConsumeFront_ConsecutiveNilBuffers(t *testing.T) {
	rb := NewBufferRing(8)
	const count = 100

	heads := make([]*[]byte, count)
	for i := 0; i < count; i++ {
		tag := []byte(fmt.Sprintf("tag-%d", i))
		heads[i] = &tag
		rb.Push(nil, heads[i])
	}

	dst := make([]byte, 16)
	for i := 0; i < count; i++ {
		n, rec := rb.PartialRead(dst)
		if n != 0 {
			t.Fatalf("expected 0 bytes copied from nil buffer, got %d", n)
		}
		if rec != heads[i] {
			t.Fatalf("head ticket mismatch at %d: expected %v, got %v", i, heads[i], rec)
		}
	}

	if rb.Length() != 0 {
		t.Fatalf("expected empty queue, got %d", rb.Length())
	}
}

var benchSinkRing RingBuffer

// BenchmarkNewBufferRing_IdleFootprint measures the exact heap memory per idle ring.
func BenchmarkNewBufferRing_IdleFootprint(b *testing.B) {
	b.ReportAllocs()
	b.ResetTimer()

	for i := 0; i < b.N; i++ {
		benchSinkRing = NewBufferRing(8)
	}
}

// TestIdleRingMemoryFootprint creates 10,000 idle ring buffers and calculates real memory per ring.
func TestIdleRingMemoryFootprint(t *testing.T) {
	const N = 10_000

	// Force clean baseline
	runtime.GC()
	runtime.GC()
	var m1, m2 runtime.MemStats
	runtime.ReadMemStats(&m1)

	// Allocate 10,000 idle ring buffers
	rings := make([]RingBuffer, N)
	for i := 0; i < N; i++ {
		rings[i] = NewBufferRing(64) // MinChunkCap = 64
	}

	runtime.ReadMemStats(&m2)
	totalBytes := m2.HeapAlloc - m1.HeapAlloc
	bytesPerRing := float64(totalBytes) / N

	t.Logf("=== Idle Ring Memory Footprint (MinChunkCap=8) ===")
	t.Logf("Total for %d idle rings: %.2f MB", N, float64(totalBytes)/(1024*1024))
	t.Logf("Exact footprint per ring: %.2f KB (%d bytes)", bytesPerRing/1024, uint64(bytesPerRing))

	// Keep slice alive so GC doesn't prematurely clean up
	if len(rings) != N {
		t.Fatal("unexpected length")
	}
}

// TestIdleShrinkOnRollover tests that an idle queue (Length == 0) resets back
// to MinChunkCap (8) on rollover and does NOT resurrect large chunks from freeChunk.
func TestIdleShrinkOnRollover(t *testing.T) {
	rb := NewBufferRing(MinChunkCap) // Starts at MinChunkCap = 8
	payload := []byte("pkt")
	head := &payload

	// =========================================================================
	// Phase 1: Burst to ramp pChunk.cap past MaxRecycleSlots (512) -> 1024
	// Total items pushed: 8 + 16 + 32 + 64 + 128 + 256 + 512 = 1,020 items (<50KB RAM)
	// =========================================================================
	for rb.pChunk.cap <= MaxRecycleSlots {
		curCap := rb.pChunk.cap
		for i := uint64(0); i < curCap; i++ {
			rb.Push(payload, head)
		}
	}

	if rb.pChunk.cap <= MaxRecycleSlots {
		t.Fatalf("Phase 1 failed: expected pChunk.cap > %d, got %d", MaxRecycleSlots, rb.pChunk.cap)
	}
	t.Logf("Phase 1: Ramped pChunk.cap to %d slots (> MaxRecycleSlots=%d)", rb.pChunk.cap, MaxRecycleSlots)

	// =========================================================================
	// Phase 2: Drain the queue completely
	// =========================================================================
	for rb.Length() > 0 {
		_, _, ok := rb.Pop()
		if !ok {
			break
		}
	}

	if rb.Length() != 0 {
		t.Fatalf("Phase 2 failed: expected queue to be empty, got %d", rb.Length())
	}

	// =========================================================================
	// Phase 3: Push in lockstep to reach rollover while idle (Length == 0)
	// =========================================================================
	// Advance pc.tail to pc.cap while popping so backlog remains 0
	rem := rb.pChunk.cap - rb.pChunk.tail
	for i := uint64(0); i < rem; i++ {
		rb.Push(payload, head)
		_, _, _ = rb.Pop()
	}

	if rb.Length() != 0 {
		t.Fatalf("Phase 3 failed: expected queue backlog to be 0 before rollover, got %d", rb.Length())
	}

	// This Push forces rollover on an empty backlog (Length == 0)
	rb.Push(payload, head)

	// =========================================================================
	// Phase 4: Assertions (Must be MinChunkCap and freeChunk must be nil)
	// =========================================================================
	if rb.pChunk.cap != MinChunkCap {
		t.Fatalf("Phase 4 FAILED (Resurrection Bug): expected pChunk.cap == MinChunkCap (%d), got %d",
			MinChunkCap, rb.pChunk.cap)
	}

	freePtr := atomic.LoadPointer(&rb.freeChunk)
	if freePtr != nil {
		t.Fatalf("Phase 4 FAILED: expected r.freeChunk == nil (dropped for GC), got %v", freePtr)
	}

	t.Logf("Phase 4 SUCCESS: Shrunk back to %d slots and freeChunk is nil.", rb.pChunk.cap)
}
func TestSPSC_RaceSoak_RecycleGenerations(t *testing.T) {
	rb := NewBufferRing(16) // Start small to force rapid initial ramp-up

	const totalCycles = 600
	var totalItemsPushed uint64

	var wg sync.WaitGroup
	wg.Add(2)

	producerErr := make(chan error, 1)
	consumerErr := make(chan error, 1)

	// Producer
	go func() {
		defer wg.Done()
		var seq uint64

		for cycle := 0; cycle < totalCycles; cycle++ {
			// Burst sizes oscillate between 20 and 3,000 items to stress
			// both steady-state recycling and chunk pool expansion
			burstSize := (cycle%50)*60 + 20

			for i := 0; i < burstSize; i++ {
				seq++
				b := make([]byte, 8)
				binary.LittleEndian.PutUint64(b, seq)

				tag := b // Use slice as its own ticket root
				rb.Push(b, &tag)
			}

			// Allow consumer to drain the entire burst down to 0,
			// forcing chunks into freeChunk across generations
			for rb.Length() > 0 {
				runtime.Gosched()
			}
		}

		atomic.StoreUint64(&totalItemsPushed, seq)
	}()

	// Consumer
	go func() {
		defer wg.Done()
		var expectedSeq uint64
		//readDst := make([]byte, 8)

		for {
			// Alternate reading mode: even cycles use Pop(), odd use PartialRead()
			usePop := (expectedSeq/50)%2 == 0

			if usePop {
				buf, head, ok := rb.Pop()
				if ok {
					expectedSeq++
					val := binary.LittleEndian.Uint64(buf)
					if val != expectedSeq {
						consumerErr <- fmt.Errorf("Pop mismatch: expected seq %d, got %d", expectedSeq, val)
						return
					}
					if head == nil || binary.LittleEndian.Uint64(*head) != expectedSeq {
						consumerErr <- fmt.Errorf("Pop ticket mismatch at seq %d", expectedSeq)
						return
					}
				} else {
					// Check if producer finished
					pushed := atomic.LoadUint64(&totalItemsPushed)
					if pushed > 0 && expectedSeq >= pushed {
						break
					}
					runtime.Gosched()
				}
			} else {
				// PartialRead mode (reads 8-byte uint64 in two 4-byte steps to stress partial reads)
				var chunkBuf [8]byte
				readTotal := 0

				for readTotal < 8 {
					dstSlice := chunkBuf[readTotal : readTotal+4]
					n, drainedTicket := rb.PartialRead(dstSlice)
					if n > 0 {
						readTotal += n
						if readTotal == 8 {
							if drainedTicket == nil {
								consumerErr <- fmt.Errorf("PartialRead: ticket was nil on final byte drain at seq %d", expectedSeq+1)
								return
							}
							expectedSeq++
							val := binary.LittleEndian.Uint64(chunkBuf[:])
							if val != expectedSeq {
								consumerErr <- fmt.Errorf("PartialRead mismatch: expected seq %d, got %d", expectedSeq, val)
								return
							}
						}
					} else {
						pushed := atomic.LoadUint64(&totalItemsPushed)
						if pushed > 0 && expectedSeq >= pushed {
							break
						}
						runtime.Gosched()
					}
				}

				pushed := atomic.LoadUint64(&totalItemsPushed)
				if pushed > 0 && expectedSeq >= pushed {
					break
				}
			}
		}
	}()

	wg.Wait()

	select {
	case err := <-producerErr:
		t.Fatalf("Producer failed: %v", err)
	case err := <-consumerErr:
		t.Fatalf("Consumer failed: %v", err)
	default:
	}

	if rb.Length() != 0 {
		t.Fatalf("expected ring buffer to be drained, got length %d", rb.Length())
	}

	t.Logf("Soak test complete: successfully processed %d items across %d burst/drain generations.",
		atomic.LoadUint64(&totalItemsPushed), totalCycles)
}
